import { useState, type ChangeEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { PERSON_ROW_SPAN, PersonCells, PersonColumnHead, PersonDetail } from '../../slots/defs/personRow';
import { SheetBody } from '../../slots/defs/sheetBody';
import { usePeople } from '../people/usePeople';
import { due, rateFor, useRates } from '../rates/useRates';
import { claimed, claimsKey, useClaims, type Claim } from './useClaims';

/** A person's claimed: the sum of their counted (OPEN or SETTLED) claims' amounts. */
function PersonClaimed({ sheetId, personId }: { sheetId: string; personId: number }) {
  const claims = useClaims(sheetId);
  return <td data-testid="person-claimed">{claimed((claims.data ?? []).filter((c) => c.personId === personId))}</td>;
}

type ClaimAction = 'open' | 'settle' | 'void';

/** A claim's status changes; the server refuses one its status does not allow. */
const ACTIONS: [ClaimAction, string][] = [
  ['open', 'Open'],
  ['settle', 'Settle'],
  ['void', 'Void'],
];

/** A person's claims, newest first, under their row, with a form that adds a claim, or edits one
 *  when its editor is open. A blank date takes the sheet's today. */
function PersonClaims({ sheetId, personId }: { sheetId: string; personId: number }) {
  const claims = useClaims(sheetId);
  const people = usePeople(sheetId);
  const rates = useRates(sheetId);
  const queryClient = useQueryClient();
  const [editing, setEditing] = useState<number | null>(null);
  const [amount, setAmount] = useState('');
  const [date, setDate] = useState('');
  const [note, setNote] = useState('');

  const clearForm = () => {
    setEditing(null);
    setAmount('');
    setDate('');
    setNote('');
  };

  const save = useMutation({
    mutationFn: (f: { id: number | null; amount: string; date: string; note: string }) => {
      const sheet = `/api/sheets/${encodeURIComponent(sheetId)}`;
      const path = f.id === null ? `${sheet}/people/${personId}/claims` : `${sheet}/claims/${f.id}`;
      return postJson<Claim>(path, { amount: f.amount, date: f.date, note: f.note });
    },
    onSuccess: async () => {
      clearForm();
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
  });

  // A status change (open, settle, void) of one claim; a refusal shows on that claim's row.
  const action = useMutation({
    mutationFn: (a: { id: number; action: ClaimAction }) =>
      postJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/${a.id}/${a.action}`, {}),
    onSettled: async () => {
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
  });

  const act = (id: number, a: ClaimAction) => {
    action.reset();
    action.mutate({ id, action: a });
  };

  const openEditor = (c: Claim) => {
    save.reset();
    action.reset();
    setEditing(c.id);
    setAmount(c.amount);
    setDate(c.date);
    setNote(c.note);
  };

  const cancel = () => {
    save.reset();
    clearForm();
  };

  const field = (set: (v: string) => void) => (e: ChangeEvent<HTMLInputElement>) => {
    set(e.target.value);
    save.reset();
  };

  const mine = (claims.data ?? []).filter((c) => c.personId === personId);
  // A claim's due: its amount at the rate for its person's grade ('n/a' when the grade has none).
  const pct = rateFor(rates.data, people.data?.find((p) => p.id === personId)?.grade);

  return (
    <tr>
      <td colSpan={PERSON_ROW_SPAN}>
        <form
          data-testid="claim-form"
          onSubmit={(e) => {
            e.preventDefault();
            save.reset();
            save.mutate({ id: editing, amount, date, note });
          }}
        >
          <label>
            Amount <input data-testid="claim-form-amount" inputMode="decimal" value={amount} onChange={field(setAmount)} />
          </label>{' '}
          <label>
            Date{' '}
            <input
              type="text"
              placeholder="yyyy-mm-dd"
              data-testid="claim-form-date"
              value={date}
              onChange={field(setDate)}
            />
          </label>{' '}
          <label>
            Note <input data-testid="claim-form-note" value={note} onChange={field(setNote)} />
          </label>{' '}
          <button type="submit" data-testid="claim-form-submit" disabled={save.isPending}>
            {editing === null ? 'Add claim' : 'Save claim'}
          </button>
          {save.isError && <p data-testid="claim-form-error">{save.error.message}</p>}
        </form>
        <table data-testid="claims-list">
          <tbody>
            {mine.map((c) => (
              <tr key={c.id} data-testid={`claim-row-${c.id}`}>
                <td data-testid="claim-amount">{c.amount}</td>
                <td data-testid="claim-date">{c.date}</td>
                <td data-testid="claim-note">{c.note}</td>
                <td data-testid="claim-due">{due(c.amount, pct)}</td>
                <td data-testid="claim-status">{c.status}</td>
                <td>
                  {ACTIONS.map(([a, label]) => (
                    <button
                      key={a}
                      type="button"
                      data-testid={`claim-${a}`}
                      disabled={action.isPending}
                      onClick={() => act(c.id, a)}
                    >
                      {label}
                    </button>
                  ))}
                  {action.isError && action.variables?.id === c.id && (
                    <span data-testid="claim-error">{action.error.message}</span>
                  )}
                </td>
                <td>
                  {editing === c.id ? (
                    <button type="button" data-testid="claim-cancel" onClick={cancel}>
                      Cancel
                    </button>
                  ) : (
                    <button type="button" data-testid="claim-edit" onClick={() => openEditor(c)}>
                      Edit
                    </button>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
        {claims.isError && <p data-testid="claims-error">{claims.error.message}</p>}
      </td>
    </tr>
  );
}

/** The sheet's claimed-total: everyone's claimed added up. */
function ClaimedTotal({ sheetId }: { sheetId: string }) {
  const claims = useClaims(sheetId);
  return (
    <p>
      Claimed total: <strong data-testid="rollup-claimed-total">{claimed(claims.data ?? [])}</strong>
    </p>
  );
}

export const contributions = [
  PersonColumnHead.fill({ order: 10, Component: () => <th>Claimed</th> }),
  PersonCells.fill({ order: 10, Component: PersonClaimed }),
  PersonDetail.fill({ order: 10, Component: PersonClaims }),
  SheetBody.fill({ order: 20, Component: ({ sheetId }) => <ClaimedTotal sheetId={sheetId} /> }),
];
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** A claim's status: DRAFT -> OPEN -> SETTLED; a DRAFT or OPEN claim can become VOID. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'SETTLED' | 'VOID';

/** A claim: its amount with two decimals, its date (yyyy-mm-dd), its note and its status. */
export type Claim = { id: number; personId: number; amount: string; date: string; note: string; status: ClaimStatus };

/** Whether a claim counts toward claimed and every total: only OPEN and SETTLED claims do. */
export function counts(c: Claim): boolean {
  return c.status === 'OPEN' || c.status === 'SETTLED';
}

export function claimsKey(sheetId: string) {
  return ['sheet', sheetId, 'claims'];
}

/** Every claim on the sheet, newest first. */
export function useClaims(sheetId: string) {
  return useQuery({
    queryKey: claimsKey(sheetId),
    queryFn: async () =>
      (await getJson<{ claims: Claim[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/claims`)).claims,
  });
}

/** The sum of the amounts of those of these claims that count, with two decimals (added up in
 *  cents, so no rounding drift). */
export function claimed(claims: Claim[]): string {
  const cents = claims.filter(counts).reduce((sum, c) => sum + Math.round(Number(c.amount) * 100), 0);
  return (cents / 100).toFixed(2);
}
// Drives the app through its screens, binding only to data-testid (AGENTS.md §2). Every test
// arranges its own data with these helpers and asserts through them or through data-testid
// directly. An action helper returns what the screen reported: an id when a row was created,
// true/false for whether the action went through or the screen refused it (its error element
// appeared). It throws when neither a result nor an error shows within the wait, so a screen that
// does nothing fails the test instead of passing as "refused".
import { expect, test, type Browser, type BrowserContext, type Locator, type Page } from '@playwright/test';
import { existsSync, readFileSync } from 'node:fs';

const AUDIT_FILE = process.env.AUDIT_FILE ?? '../.run/audit.log';
const WAIT = 8000;
const LOAD_WAIT = 30000;      // a sign-in, a sheet load or a today change: the whole sheet is re-read
const ERROR_GRACE = 2000;     // how long an error left over from the action before may linger
const AUDIT_WAIT = 3000;      // how long an audit line may lag the screen

const editing = new WeakMap<Page, string>();

export function sheetId(): string {
  return 's' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
}

/** The id a creating helper returned; throws when the screen refused (null) so the failure
 *  lands on the arranging line rather than on a later assertion. */
export function must(id: string | null): string {
  if (id === null) throw new Error('the screen refused this action (its error element appeared)');
  return id;
}

function escapeRe(s: string): string {
  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

/** The trimmed text of a locator, read without waiting: '' when it is not on the page. A poll
 *  must never use an auto-waiting read (textContent, getAttribute) on an element that may be
 *  re-rendered or removed while it polls; that read would block until the test's own timeout. */
async function shown(loc: Locator): Promise<string> {
  return ((await loc.allTextContents())[0] ?? '').trim();
}

/** The ids carried by every element matching `loc`, read without waiting. */
async function ids(loc: Locator, prefix: string): Promise<string[]> {
  const out: string[] = [];
  for (const h of await loc.elementHandles()) out.push(idOf(await h.getAttribute('data-testid'), prefix));
  return out;
}

/** The rows matching `loc` whose id is not in `before`, in screen order, each with its id and the
 *  text of the named cells; read without waiting, so a poll may call it. A creating helper finds
 *  its row this way: a page may be showing the sheet as it was when it was loaded, so the rows
 *  other users added can land on it at any moment, including between a submit and its result. */
async function freshRows(loc: Locator, prefix: string, before: string[], cells: string[]): Promise<Record<string, string>[]> {
  const out: Record<string, string>[] = [];
  try {
    for (const h of await loc.elementHandles()) {
      const testid = (await h.getAttribute('data-testid')) ?? '';
      if (!testid.startsWith(prefix) || before.includes(testid.slice(prefix.length))) continue;
      const x: Record<string, string> = { id: testid.slice(prefix.length) };
      for (const c of cells) x[c] = ((await (await h.$(`[data-testid="${c}"]`))?.textContent()) ?? '').trim();
      out.push(x);
    }
  } catch {
    return [];                            // a row was re-rendered mid-read: the poll looks again
  }
  return out;
}

/** An amount as the screen shows it: two decimals, a dot, no grouping. */
function money(amount: string): string {
  const n = Number(amount.trim());
  return amount.trim() !== '' && Number.isFinite(n) ? n.toFixed(2) : amount;
}

/** A name as a name cell shows it, without a trailing " (<grade>)" the screen may append. */
function plainName(shown: string): string {
